const decision =
  $('Determine Final Decision').first().json;

const template =
  $('Get Communication Template').first().json;

const values = {
  case_id:
    decision.case_run_id,

  business_name:
    decision.business_name,

  representative_name:
    decision.representative_name,

  outcome:
    decision.outcome,

  reason_code:
    decision.primary_reason_code,

  queue:
    decision.target_queue,

  next_action:
    decision.next_action,

  missing_items:
    Array.isArray(decision.missing_information) &&
    decision.missing_information.length > 0
      ? decision.missing_information.join(', ')
      : 'None',
};

function fillTemplate(text = '') {
  return String(text).replace(
    /\{(\w+)\}/g,
    (match, key) =>
      values[key] !== undefined
        ? String(values[key])
        : match
  );
}

return [{
  json: {
    ...decision,

    communication: {
      template_id:
        template.Template_ID,

      audience:
        template.Audience,

      subject:
        fillTemplate(
          template.Subject_Template
        ),

      body:
        fillTemplate(
          template.Body_Template
        ),

      status:
        'DRAFT',

      approval_required:
        true,

      sent:
        false,
    },
  },
}];

const caseRow =
  $('Get Case').first().json;

const resultSource =
  $('Prepare Result Source')
    .first()
    .json
    .result_source;

let utilityRows = [];

if (resultSource === 'RUNTIME') {
  utilityRows =
    $('Package Runtime Utility Results')
      .first()
      .json
      .utility_rows || [];
} else {
  utilityRows =
    $('Package Mock Utility Results')
      .first()
      .json
      .utility_rows || [];
}

const ruleRows =
  $('Get Decision Rules')
    .all()
    .map(item => item.json);

function splitSemi(value) {
  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return [];
  }

  return String(value)
    .split(';')
    .map(value => value.trim())
    .filter(Boolean);
}

function safeParse(value) {
  if (!value) {
    return {};
  }

  if (typeof value === 'object') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return {
      parse_error: true,
      raw_value: String(value)
    };
  }
}

function toBoolean(value) {
  return (
    value === true ||
    String(value).toLowerCase() === 'true' ||
    String(value).toUpperCase() === 'YES'
  );
}

const rulesById =
  Object.fromEntries(
    ruleRows.map(rule => [
      String(rule.Rule_ID).trim(),
      rule
    ])
  );

const checks =
  utilityRows.map(row => ({
    sequence:
      Number(row.Sequence || 0),

    agent_id:
      row.Agent_ID,

    utility_name:
      row.Utility_Name,

    check_type:
      row.Check_Type,

    status:
      row.Status,

    findings:
      safeParse(row.Findings_JSON),

    reason_codes:
      splitSemi(row.Reason_Codes),

    evidence_references:
      splitSemi(row.Evidence_References),

    confidence:
      Number(row.Confidence || 0),

    human_review_required:
      toBoolean(
        row.Human_Review_Required
      ),

    recommended_next_step:
      row.Recommended_Next_Step,

    rule_ids:
      splitSemi(row.Rule_IDs),

    rule_status_used:
      row.Rule_Status_Used
  }));

const requiredChecks = [
  'DOCUMENT_EXTRACTION',
  'BUSINESS_VALIDATION',
  'IDENTITY_VALIDATION',
  'AUTHORITY_VALIDATION',
  'SYSTEM_DATA_CHECK',
  'FINANCIAL_CHECK',
  'FINAL_VERIFICATION'
];

const observedCompletedCheckTypes =
  new Set(
    checks
      .filter(check =>
        String(check.status).toUpperCase() !==
        'NOT_RUN'
      )
      .map(check => check.check_type)
  );

const explicitNotRun =
  checks
    .filter(check =>
      String(check.status).toUpperCase() ===
      'NOT_RUN'
    )
    .map(check => check.check_type);

const absentMandatoryChecks =
  requiredChecks.filter(
    checkType =>
      !observedCompletedCheckTypes.has(
        checkType
      )
  );

const referencedRuleIds = [
  ...new Set(
    checks.flatMap(
      check => check.rule_ids
    )
  )
];

const applicableRules =
  referencedRuleIds
    .map(ruleId => rulesById[ruleId])
    .filter(Boolean)
    .sort(
      (a, b) =>
        Number(a.Priority ?? 9999) -
        Number(b.Priority ?? 9999)
    );

const tbdRule =
  applicableRules.find(
    rule =>
      String(rule.Rule_Status)
        .toUpperCase() ===
      'TBD'
  );

let selectedRule = null;
let governanceControlApplied = false;

if (
  resultSource === 'RUNTIME' &&
  checks.length === 0
) {
  selectedRule =
    rulesById['CTRL-002'];

  governanceControlApplied = true;

  if (!selectedRule) {
    throw new Error(
      'CTRL-002 is missing from dt_decision_rules.'
    );
  }
} else if (tbdRule) {
  selectedRule =
    rulesById['CTRL-001'];

  governanceControlApplied = true;

  if (!selectedRule) {
    throw new Error(
      'CTRL-001 is missing from dt_decision_rules.'
    );
  }
} else {
  selectedRule =
    applicableRules.find(rule =>
      [
        'REJECT',
        'NEED_MORE_INFORMATION',
        'MANUAL_REVIEW'
      ].includes(
        String(
          rule.Final_Outcome
        ).toUpperCase()
      )
    ) || null;
}

if (!selectedRule) {
  if (
    resultSource === 'RUNTIME' &&
    absentMandatoryChecks.length > 0
  ) {
    selectedRule =
      rulesById['CTRL-003'];

    governanceControlApplied = true;

    if (!selectedRule) {
      throw new Error(
        'CTRL-003 is missing from dt_decision_rules.'
      );
    }
  } else {
    const successfulChecks =
      new Set(
        checks
          .filter(check =>
            [
              'PASS',
              'PASS_WITH_FLAG'
            ].includes(
              String(check.status)
                .toUpperCase()
            )
          )
          .map(check =>
            check.check_type
          )
      );

    const failedCompleteness =
      requiredChecks.filter(
        checkType =>
          !successfulChecks.has(
            checkType
          )
      );

    if (
      failedCompleteness.length > 0
    ) {
      throw new Error(
        `Approval blocked. Mandatory checks incomplete: ${failedCompleteness.join(', ')}`
      );
    }

    selectedRule =
      rulesById['FINAL-001'];

    if (!selectedRule) {
      throw new Error(
        'FINAL-001 is missing from dt_decision_rules.'
      );
    }
  }
}

const outcome =
  String(
    selectedRule.Final_Outcome
  ).toUpperCase();

const missingInformation = [];

for (const check of checks) {
  const missing =
    check.findings?.missing;

  if (Array.isArray(missing)) {
    missingInformation.push(
      ...missing
    );
  }
}

if (
  applicableRules.some(
    rule =>
      rule.Reason_Code ===
      'AUTHORITY_MISSING'
  ) &&
  !missingInformation.includes(
    'AUTHORITY_LETTER'
  )
) {
  missingInformation.push(
    'AUTHORITY_LETTER'
  );
}

const conflicts = [];

for (const check of checks) {
  const findings =
    check.findings || {};

  if (
    findings.legal_name_conflict ===
    true
  ) {
    conflicts.push(
      'Conflicting legal names exist across CRM records.'
    );
  }

  if (
    findings.open_duplicate_request ===
    true
  ) {
    conflicts.push(
      'Another authority request is already open.'
    );
  }

  if (
    String(findings.scope)
      .toUpperCase() ===
    'AMBIGUOUS'
  ) {
    conflicts.push(
      'The submitted authority scope is ambiguous.'
    );
  }

  if (
    findings.security_flag &&
    String(findings.security_flag)
      .toUpperCase() !==
    'NONE'
  ) {
    conflicts.push(
      'A document security flag requires specialist review.'
    );
  }

  if (
    String(findings.lookup_status)
      .toUpperCase() ===
    'UNAVAILABLE'
  ) {
    conflicts.push(
      'The business-register lookup is unavailable.'
    );
  }
}

const allReasonCodes = [
  ...new Set(
    checks.flatMap(
      check => check.reason_codes
    )
  )
];

const assumptionsUsed =
  applicableRules
    .filter(
      rule =>
        String(rule.Rule_Status)
          .toUpperCase() ===
        'ASSUMPTION'
    )
    .map(rule => rule.Rule_ID);

const checksNotRun = [
  ...new Set([
    ...explicitNotRun,
    ...(resultSource === 'RUNTIME'
      ? absentMandatoryChecks
      : [])
  ])
];

let customerSafeSummary;

switch (outcome) {
  case 'APPROVE':
    customerSafeSummary =
      'The prototype assessment completed all mandatory checks successfully. The request is eligible to proceed to the next operational step.';
    break;

  case 'NEED_MORE_INFORMATION':
    customerSafeSummary =
      'The assessment cannot be completed until the requested information is supplied.';
    break;

  case 'MANUAL_REVIEW':
    customerSafeSummary =
      'The assessment identified information that requires review by an operations specialist. No final adverse decision has been made.';
    break;

  case 'REJECT':
    customerSafeSummary =
      'The prototype identified a condition that prevents automated progression. Human confirmation is required before final disposition.';
    break;

  default:
    customerSafeSummary =
      'The assessment requires further processing.';
}

const decision = {
  case_run_id:
    caseRow.Case_Run_ID,

  case_id:
    caseRow.Case_ID,

  submission_version:
    Number(
      caseRow.Submission_Version
    ),

  country:
    caseRow.Country,

  request_type:
    caseRow.Request_Type,

  business_name:
    caseRow.Business_Name_Submitted,

  business_identifier:
    caseRow.Business_Identifier_Submitted,

  customer_id:
    caseRow.Customer_ID,

  representative_name:
    caseRow.Representative_Name,

  result_source:
    resultSource,

  outcome,

  primary_reason_code:
    selectedRule.Reason_Code,

  secondary_reason_codes:
    allReasonCodes,

  human_review_required:
    toBoolean(
      selectedRule
        .Human_Review_Required
    ),

  target_queue:
    selectedRule.Target_Queue,

  next_action:
    selectedRule.Next_Action,

  communication_template_id:
    selectedRule
      .Communication_Template_ID,

  applied_rule_id:
    selectedRule.Rule_ID,

  applied_rule_status:
    selectedRule.Rule_Status,

  governance_control_applied:
    governanceControlApplied,

  triggering_tbd_rule:
    tbdRule
      ? tbdRule.Rule_ID
      : null,

  missing_information: [
    ...new Set(
      missingInformation
    )
  ],

  conflicts: [
    ...new Set(conflicts)
  ],

  assumptions_used:
    assumptionsUsed,

  completed_checks:
    checks.filter(
      check =>
        String(check.status)
          .toUpperCase() !==
        'NOT_RUN'
    ),

  checks_not_run:
    checksNotRun,

  customer_safe_summary:
    customerSafeSummary,

  prototype_data:
    true,

  production_write_performed:
    false
};

return [
  {
    json: decision
  }
];

const rows = $input
  .all()
  .map(item => item.json)
  .filter(row =>
    String(row.Case_Run_ID || '').trim()
  );

return [
  {
    json: {
      result_source: 'MOCK',
      utility_rows: rows
    }
  }
];

/*
============================================================
PACKAGE RUNTIME UTILITY RESULTS
============================================================

Purpose:
- Read only the current input from Get Runtime Utility Results.
- Normalise runtime-table column names and data types.
- Filter to the requested case/version.
- Remove superseded rows.
- Keep one current row per check type.
- Preserve all seven mandatory checks.
- Produce diagnostic counts for troubleshooting.
============================================================
*/

const preparedSource =
  $('Prepare Result Source')
    .first()
    .json || {};

const expectedCaseRunId =
  String(
    preparedSource.case_run_id || ''
  ).trim();

const expectedSubmissionVersion =
  Number(
    preparedSource.submission_version || 1
  );

/*
------------------------------------------------------------
HELPERS
------------------------------------------------------------
*/

function pick(object, ...keys) {
  for (const key of keys) {
    const value =
      object?.[key];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return '';
}

function toBoolean(value) {
  return (
    value === true ||
    String(value)
      .trim()
      .toLowerCase() === 'true' ||
    String(value)
      .trim()
      .toUpperCase() === 'YES'
  );
}

function asTimestamp(value) {
  const parsed =
    Date.parse(
      String(value || '')
    );

  return Number.isFinite(parsed)
    ? parsed
    : 0;
}

/*
------------------------------------------------------------
READ CURRENT NODE INPUT ONLY
------------------------------------------------------------

The Package node must be connected directly after
Get Runtime Utility Results.

Do not replace $input.all() with:
- $('Get Decision Rules').all()
- $('Get Runtime Utility Results').first()
- $('Get Runtime Utility Results').item
*/

const sourceRows =
  $input
    .all()
    .map(
      (item, index) => ({
        ...(item.json || {}),

        __input_index:
          index,
      })
    );

/*
------------------------------------------------------------
NORMALISE RUNTIME ROWS
------------------------------------------------------------
*/

const normalisedRows =
  sourceRows
    .map(row => {
      const caseRunId =
        String(
          pick(
            row,
            'case_run_id',
            'Case_Run_ID'
          )
        ).trim();

      const submissionVersion =
        Number(
          pick(
            row,
            'submission_version',
            'Submission_Version'
          ) || 1
        );

      const checkType =
        String(
          pick(
            row,
            'check_type',
            'Check_Type'
          )
        )
          .trim()
          .toUpperCase();

      /*
      Ignore the empty placeholder that Always Output Data
      can emit when no row is found.
      */
      if (
        !caseRunId ||
        !checkType
      ) {
        return null;
      }

      return {
        Case_Run_ID:
          caseRunId,

        Submission_Version:
          submissionVersion,

        Sequence:
          Number(
            pick(
              row,
              'sequence',
              'Sequence'
            ) || 0
          ),

        Agent_ID:
          String(
            pick(
              row,
              'agent_id',
              'Agent_ID'
            )
          ).trim(),

        Utility_Name:
          String(
            pick(
              row,
              'utility_name',
              'Utility_Name'
            )
          ).trim(),

        Check_Type:
          checkType,

        Status:
          String(
            pick(
              row,
              'status',
              'Status'
            )
          )
            .trim()
            .toUpperCase(),

        Findings_JSON:
          pick(
            row,
            'findings_json',
            'Findings_JSON'
          ),

        Reason_Codes:
          String(
            pick(
              row,
              'reason_codes',
              'Reason_Codes'
            )
          ).trim(),

        Evidence_References:
          String(
            pick(
              row,
              'evidence_references',
              'Evidence_References'
            )
          ).trim(),

        Confidence:
          Number(
            pick(
              row,
              'confidence',
              'Confidence'
            ) || 0
          ),

        Human_Review_Required:
          toBoolean(
            pick(
              row,
              'human_review_required',
              'Human_Review_Required'
            )
          ),

        Recommended_Next_Step:
          String(
            pick(
              row,
              'recommended_next_step',
              'Recommended_Next_Step'
            )
          ).trim(),

        Rule_IDs:
          String(
            pick(
              row,
              'rule_ids',
              'Rule_IDs'
            )
          ).trim(),

        Rule_Status_Used:
          String(
            pick(
              row,
              'rule_status_used',
              'Rule_Status_Used'
            )
          ).trim(),

        Created_At:
          String(
            pick(
              row,
              'created_at',
              'Created_At',
              'createdAt'
            )
          ).trim(),

        Updated_At:
          String(
            pick(
              row,
              'updated_at',
              'Updated_At',
              'updatedAt'
            )
          ).trim(),

        Superseded:
          toBoolean(
            pick(
              row,
              'superseded',
              'Superseded'
            )
          ),

        __input_index:
          Number(
            row.__input_index || 0
          ),
      };
    })
    .filter(Boolean);

/*
------------------------------------------------------------
FILTER TO THE REQUESTED CASE/VERSION
------------------------------------------------------------
*/

const crossCaseRows =
  normalisedRows.filter(row =>
    row.Case_Run_ID !==
      expectedCaseRunId ||
    row.Submission_Version !==
      expectedSubmissionVersion
  );

const relevantRows =
  normalisedRows.filter(row =>
    row.Case_Run_ID ===
      expectedCaseRunId &&
    row.Submission_Version ===
      expectedSubmissionVersion &&
    row.Superseded !== true
  );

/*
------------------------------------------------------------
KEEP ONE CURRENT ROW PER CHECK TYPE
------------------------------------------------------------

Key:
case_run_id + submission_version + check_type

Where an unexpected duplicate exists:
1. prefer the most recently updated row;
2. then the most recently created row;
3. then the later incoming item.
*/

const rowsByCheckType =
  new Map();

for (const candidate of relevantRows) {
  const key =
    candidate.Check_Type;

  const existing =
    rowsByCheckType.get(key);

  if (!existing) {
    rowsByCheckType.set(
      key,
      candidate
    );

    continue;
  }

  const existingUpdatedAt =
    asTimestamp(
      existing.Updated_At
    );

  const candidateUpdatedAt =
    asTimestamp(
      candidate.Updated_At
    );

  const existingCreatedAt =
    asTimestamp(
      existing.Created_At
    );

  const candidateCreatedAt =
    asTimestamp(
      candidate.Created_At
    );

  const candidateIsLater =
    (
      candidateUpdatedAt >
      existingUpdatedAt
    ) ||
    (
      candidateUpdatedAt ===
        existingUpdatedAt &&
      candidateCreatedAt >
        existingCreatedAt
    ) ||
    (
      candidateUpdatedAt ===
        existingUpdatedAt &&
      candidateCreatedAt ===
        existingCreatedAt &&
      candidate.__input_index >
        existing.__input_index
    );

  if (candidateIsLater) {
    rowsByCheckType.set(
      key,
      candidate
    );
  }
}

const utilityRows =
  Array.from(
    rowsByCheckType.values()
  )
    .sort(
      (a, b) =>
        Number(a.Sequence) -
        Number(b.Sequence)
    )
    .map(row => ({
      Case_Run_ID:
        row.Case_Run_ID,

      Submission_Version:
        row.Submission_Version,

      Sequence:
        row.Sequence,

      Agent_ID:
        row.Agent_ID,

      Utility_Name:
        row.Utility_Name,

      Check_Type:
        row.Check_Type,

      Status:
        row.Status,

      Findings_JSON:
        row.Findings_JSON,

      Reason_Codes:
        row.Reason_Codes,

      Evidence_References:
        row.Evidence_References,

      Confidence:
        row.Confidence,

      Human_Review_Required:
        row.Human_Review_Required,

      Recommended_Next_Step:
        row.Recommended_Next_Step,

      Rule_IDs:
        row.Rule_IDs,

      Rule_Status_Used:
        row.Rule_Status_Used,
    }));

/*
------------------------------------------------------------
DIAGNOSTICS
------------------------------------------------------------
*/

const mandatoryChecks = [
  'DOCUMENT_EXTRACTION',
  'BUSINESS_VALIDATION',
  'IDENTITY_VALIDATION',
  'AUTHORITY_VALIDATION',
  'SYSTEM_DATA_CHECK',
  'FINANCIAL_CHECK',
  'FINAL_VERIFICATION',
];

const packagedCheckTypes =
  utilityRows.map(row =>
    row.Check_Type
  );

const packagedCheckTypeSet =
  new Set(
    packagedCheckTypes
  );

const missingMandatoryChecks =
  mandatoryChecks.filter(
    checkType =>
      !packagedCheckTypeSet.has(
        checkType
      )
  );

const duplicateRowsRemoved =
  Math.max(
    0,
    relevantRows.length -
      utilityRows.length
  );

/*
------------------------------------------------------------
RETURN ONE PACKAGE
------------------------------------------------------------
*/

return [
  {
    json: {
      result_source:
        'RUNTIME',

      expected_case_run_id:
        expectedCaseRunId,

      expected_submission_version:
        expectedSubmissionVersion,

      source_row_count:
        sourceRows.length,

      normalised_row_count:
        normalisedRows.length,

      relevant_active_row_count:
        relevantRows.length,

      runtime_row_count:
        utilityRows.length,

      duplicate_rows_removed:
        duplicateRowsRemoved,

      cross_case_row_count:
        crossCaseRows.length,

      packaged_check_types:
        packagedCheckTypes,

      missing_mandatory_checks:
        missingMandatoryChecks,

      utility_rows:
        utilityRows,
    },
  },
];
